"""Execute bound queries through ordered, materialized contract stages."""

from __future__ import annotations

from dataclasses import dataclass
from functools import cmp_to_key
import math
import re

from .errors import QueryRuntimeError
from .model import Result
from .semantic import BoundExpr, BoundQuery


@dataclass(frozen=True)
class _Context:
    row: tuple = ()
    keys: tuple = ()
    aggregates: tuple = ()


def _truth(value):
    return None if value is None else int(value != 0)


def _runtime(message: str, expression: BoundExpr) -> None:
    token = expression.token
    raise QueryRuntimeError(message, token.line, token.column)


def _quotient(left: int, right: int) -> int:
    value = abs(left) // abs(right)
    return -value if (left < 0) != (right < 0) else value


def _like(value: str, pattern: str, escape: str | None, expression: BoundExpr) -> int:
    pieces = []
    index = 0
    while index < len(pattern):
        character = pattern[index]
        if character == escape:
            index += 1
            if index == len(pattern) or pattern[index] not in ("%", "_", escape):
                _runtime("invalid LIKE pattern", expression)
            pieces.append(re.escape(pattern[index]))
        elif character == "%":
            pieces.append(".*")
        elif character == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(character))
        index += 1
    return int(re.fullmatch("".join(pieces), value, flags=re.DOTALL) is not None)


def evaluate(expression: BoundExpr, context: _Context):
    """Evaluate a statically checked expression; SQL predicates never return bool."""
    kind = expression.kind
    if kind == "literal":
        return expression.value
    if kind == "column":
        return context.row[expression.value]
    if kind == "group":
        return context.keys[expression.slot]
    if kind == "aggregate":
        return context.aggregates[expression.slot]
    if kind == "unary":
        value = evaluate(expression.children[0], context)
        if value is None:
            return None
        if expression.value == "NOT":
            return 1 - _truth(value)
        return -value if expression.value == "-" else +value
    if kind == "binary":
        operator = expression.value
        left = evaluate(expression.children[0], context)
        if operator == "AND":
            left = _truth(left)
            if left == 0:
                return 0
            right = _truth(evaluate(expression.children[1], context))
            return 0 if right == 0 else None if left is None or right is None else 1
        if operator == "OR":
            left = _truth(left)
            if left == 1:
                return 1
            right = _truth(evaluate(expression.children[1], context))
            return 1 if right == 1 else None if left is None or right is None else 0
        right = evaluate(expression.children[1], context)
        if left is None or right is None:
            return None
        if operator in ("/", "%"):
            if right == 0:
                _runtime("division by zero", expression)
            if expression.type == "REAL":
                return left / right if operator == "/" else math.fmod(left, right)
            quotient = _quotient(left, right)
            return quotient if operator == "/" else left - quotient * right
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "=":
            return int(left == right)
        if operator in ("!=", "<>"):
            return int(left != right)
        if operator == "<":
            return int(left < right)
        if operator == "<=":
            return int(left <= right)
        if operator == ">":
            return int(left > right)
        if operator == ">=":
            return int(left >= right)
    if kind == "is_null":
        value = evaluate(expression.children[0], context)
        return int(value is not None) if expression.value else int(value is None)
    if kind == "like":
        value = evaluate(expression.children[0], context)
        pattern = evaluate(expression.children[1], context)
        if value is None or pattern is None:
            return None
        negate, escape = expression.value
        result = _like(value, pattern, escape, expression)
        return 1 - result if negate else result
    if kind == "in":
        value = evaluate(expression.children[0], context)
        if value is None:
            return None
        # Only AND/OR may skip a non-NULL-LHS operand. A prior match cannot
        # conceal a later list-item failure (decision D3).
        items = [evaluate(item, context) for item in expression.children[1:]]
        result = (1 if any(item is not None and item == value for item in items)
                  else None if any(item is None for item in items) else 0)
        return 1 - result if expression.value and result is not None else result
    raise AssertionError(f"unhandled bound expression: {kind}")


def _joined_rows(query: BoundQuery) -> list[tuple]:
    rows = list(query.ranges[0].table.rows) if query.ranges else [()]
    for join in query.joins:
        joined = []
        for left in rows:
            matched = False
            for right in join.range.table.rows:
                row = left + right
                if _truth(evaluate(join.condition, _Context(row))) == 1:
                    joined.append(row)
                    matched = True
            if join.kind == "LEFT" and not matched:
                joined.append(left + (None,) * len(join.range.table.columns))
        rows = joined
    return rows


def _aggregate(expression: BoundExpr, values: list):
    if expression.value == "COUNT":
        return len(values) if not expression.children else sum(value is not None for value in values)
    non_null = [value for value in values if value is not None]
    if not non_null:
        return None
    if expression.value == "SUM":
        return sum(non_null)
    if expression.value == "AVG":
        return sum(non_null) / len(non_null)
    if expression.value == "MIN":
        return min(non_null)
    return max(non_null)


def _grouped_contexts(query: BoundQuery, rows: list[tuple]) -> list[_Context]:
    groups = {} if query.group_by else {(): [[] for _ in query.aggregates]}
    for row in rows:
        context = _Context(row)
        keys = tuple(evaluate(key, context) for key in query.group_by)
        arguments = [evaluate(aggregate.children[0], context) if aggregate.children else None
                     for aggregate in query.aggregates]
        if keys not in groups:
            groups[keys] = [[] for _ in query.aggregates]
        for values, argument in zip(groups[keys], arguments):
            values.append(argument)
    return [_Context(keys=keys, aggregates=tuple(_aggregate(aggregate, values)
                                                for aggregate, values in zip(query.aggregates, arguments)))
            for keys, arguments in groups.items()]


def _compare_values(left, right) -> int:
    if left is None:
        return 0 if right is None else -1
    if right is None:
        return 1
    return int(left > right) - int(left < right)


def execute(query: BoundQuery) -> Result:
    # Each list below is a whole-input barrier. In particular no ORDER key is
    # evaluated until every surviving projection has finished successfully.
    rows = _joined_rows(query)
    if query.where is not None:
        rows = [row for row in rows if _truth(evaluate(query.where, _Context(row))) == 1]
    contexts = (_grouped_contexts(query, rows) if query.aggregate_query
                else [_Context(row) for row in rows])
    if query.having is not None:
        contexts = [context for context in contexts
                    if _truth(evaluate(query.having, context)) == 1]
    projected = [tuple(evaluate(expression, context) for expression in query.select)
                 for context in contexts]
    keyed = [(row, tuple(row[order.output_index] if order.output_index is not None
                         else evaluate(order.expression, context) for order in query.order_by))
             for row, context in zip(projected, contexts)]
    if query.distinct:
        seen = set()
        distinct = []
        for row, keys in keyed:
            if row not in seen:
                seen.add(row)
                distinct.append((row, keys))
        keyed = distinct
    if query.order_by:
        def compare(left, right):
            for a, b, order in zip(left[1], right[1], query.order_by):
                comparison = _compare_values(a, b)
                if comparison:
                    return -comparison if order.descending else comparison
            return 0
        keyed.sort(key=cmp_to_key(compare))
    result_rows = [row for row, _ in keyed]
    result_rows = result_rows[query.offset:]
    if query.limit is not None:
        result_rows = result_rows[:query.limit]
    return Result(query.columns, [expression.type for expression in query.select], result_rows)

"""The public, read-only library connection facade."""

from __future__ import annotations

from os import PathLike

from .catalog import Catalog
from .executor import execute
from .model import Result
from .parser import parse
from .semantic import bind


class Connection:
    def __init__(self, data_dir: str | PathLike) -> None:
        self._catalog = Catalog(data_dir)

    def execute(self, sql: str) -> Result:
        query = parse(sql)
        bound = bind(query, self._catalog)
        return execute(bound)

    def tables(self) -> list[str]:
        return self._catalog.tables()

    def schema(self, table: str) -> list[tuple[str, str]]:
        return self._catalog.schema(table)


def connect(data_dir: str | PathLike) -> Connection:
    return Connection(data_dir)

